+      () => manager.attachSession("default", created.key.sessionId),
+      (error) =>
+        error instanceof AgentManagerError &&
+        error.code === "session_start_failed" &&
+        error.message === "pi start failed",
+    );
+
+    const status = manager.getStatus(created.key);
+    assert.equal(status?.state, AgentLifecycleState.Failed);
+    assert.equal(status?.error, "pi start failed");
+  });
+});

import { mkdir, readdir, stat } from "node:fs/promises";
import path from "node:path";

import type { PileSummary } from "../shared/types.js";
import { StorageError } from "./errors.js";
import {
  AssertPilePathWithinRoot,
  CreateStoragePaths,
  ResolveManifestFilePath,
  ResolvePileDirectory,
  type StoragePaths,
} from "./paths.js";
import { ValidatePileName } from "./validation.js";

export type { StoragePaths };

async function ReadManifestUpdatedAt(manifestPath: string): Promise<string | null>
{
  try
  {
    const manifestStat = await stat(manifestPath);
    return manifestStat.mtime.toISOString();
  }
  catch
  {
    return null;
  }
}

export async function CreatePile(paths: StoragePaths, pile: string): Promise<PileSummary>
{
  const validatedPile = ValidatePileName(pile);
  const pileDirectory = ResolvePileDirectory(paths, validatedPile);
  await mkdir(pileDirectory, { recursive: true });
  await AssertPilePathWithinRoot(paths, pileDirectory);

  return {
    pile: validatedPile,
    sessionCount: 0,
    latestUpdatedAt: null,
  };
}

export async function ListPiles(paths: StoragePaths): Promise<PileSummary[]>
{
  await mkdir(paths.pilesDir, { recursive: true });

  let entries: string[];

  try
  {
    entries = await readdir(paths.pilesDir);
  }
  catch
  {
    return [];
  }

  const summaries: PileSummary[] = [];

  for (const entry of entries)
  {
    let validatedPile: string;

    try
    {
      validatedPile = ValidatePileName(entry);
    }
    catch
    {
      continue;
    }

    const pileDirectory = path.join(paths.pilesDir, validatedPile);
    const pileStat = await stat(pileDirectory);

    if (!pileStat.isDirectory())
    {
      continue;
    }

    let sessionCount = 0;
    let latestUpdatedAt: string | null = null;
    const pileEntries = await readdir(pileDirectory);

    for (const pileEntry of pileEntries)
    {
      if (!pileEntry.endsWith(".manifest.json"))
      {
        continue;
      }

      sessionCount += 1;
      const manifestPath = path.join(pileDirectory, pileEntry);
      const updatedAt = await ReadManifestUpdatedAt(manifestPath);

      if (updatedAt !== null && (latestUpdatedAt === null || updatedAt > latestUpdatedAt))
      {
        latestUpdatedAt = updatedAt;
      }
    }

    summaries.push({
      pile: validatedPile,
      sessionCount,
      latestUpdatedAt,
    });
  }

  summaries.sort((left, right) => left.pile.localeCompare(right.pile));
  return summaries;
}

export async function EnsurePileExists(paths: StoragePaths, pile: string): Promise<void>
{
  const validatedPile = ValidatePileName(pile);
  const pileDirectory = ResolvePileDirectory(paths, validatedPile);

  try
  {
    const pileStat = await stat(pileDirectory);

    if (!pileStat.isDirectory())
    {
      throw new StorageError("pile_not_found", `pile not found: ${validatedPile}`);
    }
  }
  catch (error)
  {
    if (error instanceof StorageError)
    {
      throw error;
    }

    throw new StorageError("pile_not_found", `pile not found: ${validatedPile}`);
  }

  await AssertPilePathWithinRoot(paths, pileDirectory);
}

export async function ManifestExists(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<boolean>
{
  try
  {
    await stat(ResolveManifestFilePath(paths, pile, sessionId));
    return true;
  }
  catch
  {
    return false;
  }
}

import { readFile, readdir, writeFile } from "node:fs/promises";

import type {
  SessionManifest,
  UpdateManifestInput,
  WriteInitialManifestInput,
} from "../shared/types.js";
import { x_manifestSchemaVersion } from "../shared/types.js";
import { StorageError } from "./errors.js";
import { EnsurePileExists } from "./piles.js";
import {
  ManifestSessionFileReference,
  ResolveManifestFilePath,
  ResolvePileDirectory,
  type StoragePaths,
} from "./paths.js";
import { ValidateSessionId } from "./validation.js";

function ParseManifest(raw: string, pile: string, sessionId: string): SessionManifest
{
  let parsed: SessionManifest;

  try
  {
    parsed = JSON.parse(raw) as SessionManifest;
  }
  catch
  {
    throw new StorageError("invalid_manifest", "manifest is not valid JSON");
  }

  if (parsed.pile !== pile || parsed.sessionId !== sessionId)
  {
    throw new StorageError("invalid_manifest", "manifest identity does not match request");
  }

  return parsed;
}

export async function ReadManifest(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionManifest>
{
  await EnsurePileExists(paths, pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  const manifestPath = ResolveManifestFilePath(paths, pile, validatedSessionId);

  let raw: string;

  try
  {
    raw = await readFile(manifestPath, "utf8");
  }
  catch
  {
    throw new StorageError(
      "manifest_not_found",
      `manifest not found for session ${validatedSessionId}`,
    );
  }

  return ParseManifest(raw, pile, validatedSessionId);
}

export async function ListSessionManifests(
  paths: StoragePaths,
  pile: string,
): Promise<SessionManifest[]>
{
  await EnsurePileExists(paths, pile);
  const pileDirectory = ResolvePileDirectory(paths, pile);
  const entries = await readdir(pileDirectory);
  const manifests: SessionManifest[] = [];

  for (const entry of entries)
  {
    if (!entry.endsWith(".manifest.json"))
    {
      continue;
    }

    const sessionId = entry.slice(0, -".manifest.json".length);

    try
    {
      ValidateSessionId(sessionId);
      manifests.push(await ReadManifest(paths, pile, sessionId));
    }
    catch
    {
      continue;
    }
  }

  manifests.sort((left, right) => right.updatedAt.localeCompare(left.updatedAt));
  return manifests;
}

export async function WriteInitialManifest(
  paths: StoragePaths,
  input: WriteInitialManifestInput,
): Promise<SessionManifest>
{
  await EnsurePileExists(paths, input.pile);
  const validatedSessionId = ValidateSessionId(input.sessionId);
  const manifestPath = ResolveManifestFilePath(paths, input.pile, validatedSessionId);
  const now = new Date().toISOString();
  const manifest: SessionManifest = {
    schemaVersion: x_manifestSchemaVersion,
    pile: input.pile,
    sessionId: validatedSessionId,
    chatName: input.chatName,
    description: input.description,
    rootDirectory: input.rootDirectory,
    createdAt: now,
    updatedAt: now,
    lastOpenedAt: now,
    model: input.model,
    pi: {
      sessionFile: ManifestSessionFileReference(paths.repoRoot, input.pile, validatedSessionId),
      extensionVersion: input.extensionVersion,
    },
    history: {
      messageCount: input.messageCount ?? 0,
      lastSequence: input.lastSequence ?? 0,
    },
  };

  await writeFile(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
  return manifest;
}

export async function UpdateManifest(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  update: UpdateManifestInput,
): Promise<SessionManifest>
{
  const manifest = await ReadManifest(paths, pile, sessionId);
  const updated: SessionManifest = {
    ...manifest,
    chatName: update.chatName ?? manifest.chatName,
    description: update.description ?? manifest.description,
    rootDirectory: update.rootDirectory ?? manifest.rootDirectory,
    model: update.model ?? manifest.model,
    lastOpenedAt: update.lastOpenedAt ?? manifest.lastOpenedAt,
    updatedAt: new Date().toISOString(),
    history: {
      messageCount: update.messageCount ?? manifest.history.messageCount,
      lastSequence: update.lastSequence ?? manifest.history.lastSequence,
    },
  };

  const manifestPath = ResolveManifestFilePath(paths, pile, sessionId);
  await writeFile(manifestPath, `${JSON.stringify(updated, null, 2)}\n`, "utf8");
  return updated;
}

import { realpath } from "node:fs/promises";
import path from "node:path";

import { GetDefaultSheafChatPaths } from "../server/repo_paths.js";
import { StorageError } from "./errors.js";
import { ValidatePileName, ValidateSessionId } from "./validation.js";

export const x_pilesDirRelative = "data/sheaf-chat/sessions/piles";
export const x_historyFileSuffix = ".sheaf-history.jsonl";
export const x_manifestFileSuffix = ".manifest.json";
export const x_provisionalFileSuffix = ".provisional.json";
export const x_sessionFileSuffix = ".jsonl";

export interface StoragePaths
{
  repoRoot: string;
  dataDir: string;
  sessionsDir: string;
  pilesDir: string;
}

export function CreateStoragePaths(repoRoot: string): StoragePaths
{
  const defaults = GetDefaultSheafChatPaths(repoRoot);

  return {
    repoRoot,
    dataDir: defaults.dataDir,
    sessionsDir: defaults.sessionsDir,
    pilesDir: path.join(defaults.sessionsDir, "piles"),
  };
}

export function ResolvePileDirectory(paths: StoragePaths, pile: string): string
{
  const validatedPile = ValidatePileName(pile);
  return path.join(paths.pilesDir, validatedPile);
}

export function ResolveSessionStem(paths: StoragePaths, pile: string, sessionId: string): string
{
  const pileDir = ResolvePileDirectory(paths, pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  return path.join(pileDir, validatedSessionId);
}

export function ResolveSessionFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_sessionFileSuffix}`;
}

export function ResolveManifestFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_manifestFileSuffix}`;
}

export function ResolveHistoryFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_historyFileSuffix}`;
}

export function ResolveProvisionalFilePath(paths: StoragePaths, pile: string, sessionId: string): string
{
  const validatedSessionId = ValidateSessionId(sessionId);
  return `${ResolveSessionStem(paths, pile, sessionId)}${x_provisionalFileSuffix}`;
}

export function ResolveRootDirectory(repoRoot: string, rootDirectory: string): string
{
  if (path.isAbsolute(rootDirectory))
  {
    return path.resolve(rootDirectory);
  }

  return path.resolve(repoRoot, rootDirectory);
}

export function ManifestSessionFileReference(
  repoRoot: string,
  pile: string,
  sessionId: string,
): string
{
  const validatedPile = ValidatePileName(pile);
  const validatedSessionId = ValidateSessionId(sessionId);
  return path.join(
    x_pilesDirRelative,
    validatedPile,
    `${validatedSessionId}${x_sessionFileSuffix}`,
  );
}

async function ResolveExistingPath(targetPath: string): Promise<string>
{
  const resolved = path.resolve(targetPath);

  try
  {
    return await realpath(resolved);
  }
  catch (error)
  {
    const nodeError = error as NodeJS.ErrnoException;

    if (nodeError.code !== "ENOENT")
    {
      throw error;
    }
  }

  return resolved;
}

export async function AssertPathWithinRoot(
  candidatePath: string,
  rootPath: string,
): Promise<string>
{
  const resolvedRoot = await ResolveExistingPath(rootPath);
  const resolvedCandidate = await ResolveExistingPath(candidatePath);
  const relative = path.relative(resolvedRoot, resolvedCandidate);

  if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative)))
  {
    return resolvedCandidate;
  }

  throw new StorageError("path_escape", "path escapes the storage root");
}

export async function AssertPilePathWithinRoot(
  paths: StoragePaths,
  pileDirectory: string,
): Promise<string>
{
  return AssertPathWithinRoot(pileDirectory, paths.pilesDir);
}
